insert into public.zonas_domicilio (nombre, valor)
select j.nombre, j.valor
  from jasta j
 where not exists (select 1 from public.zonas_domicilio z where lower(translate(trim(z.nombre), 'áéíóúÁÉÍÓÚüÜ', 'aeiouAEIOUuU')) = lower(translate(trim(j.nombre), 'áéíóúÁÉÍÓÚüÜ', 'aeiouAEIOUuU')))
on conflict (nombre) do update set valor = excluded.valor;
